WITH removed AS ( DELETE FROM email_message_labels WHERE $3::bool AND message_id = $1::uuid AND label_id NOT IN (SELECT UNNEST($2::uuid[])) AND label_id NOT IN ( SELECT id FROM email_labels WHERE link_id = $4 AND provider_label_id = ANY($5::text[]) ) ) INSERT INTO email_message_labels (message_id, label_id) SELECT $1, label_id FROM UNNEST($2::uuid[]) AS t(label_id) ON CONFLICT (message_id, label_id) DO NOTHING
